if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }


// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#ff5e62", "#ff9966", "#ffe066", "#2c3e50", "#3498db"];
var speedMult = 1.0;
var lineScale = 1.0;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by 'recursiveorbits' by 'Aaron Reuland (a_ soluble_fish)' ===
// Created as variant #2 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
//Keeping it simple and graceful.

let m, center, speed, offsetInc
let colors = ["#2a274a", "#3d3829", "#729880", "#d0d074", "#719c67", "#70732b", "#a6690e"]
let offsetter = 0

function setup() {
	m = max(windowWidth, windowHeight)
	createCanvas(m, m);
	center = createVector(width * 0.5, height * 0.5)
	offsetInc = TAU / 7
	noStroke()
}

function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);

	background("#a53c0b")
	offsetter = 0
	speed = frameCount * 0.01
	for (let i = 0; i < colors.length; i++) {
		fill(colors[i])
		let sizer = map(i, 0, colors.length, m * 0.2, m * 0.175)
		body(center, 0, sizer, 0, 1)
	}

  pop();
}

function body(fulcrum, orbitR, s, offset, depth) {
	rspeed = speed * depth
	let newPos = createVector(fulcrum.x + (cos(offset + rspeed) * orbitR), fulcrum.y + (sin(offset + rspeed) * orbitR))
	circle(newPos.x, newPos.y, s)
	if (depth < 6) {
		offsetter += offsetInc
		let newS = s * 0.5
		body(newPos, newS * 2.75, newS, offsetter, depth + 1)
	}
}
